import{_ as o,o as a,c as t,a8 as r}from"./chunks/framework.BWjTbCIc.js";const n="/hk-exam-web/assets/exam-papers/css-s1-language-acquisition.png",u=JSON.parse('{"title":"启思中学 · 年份未注明 · 中一 · 考试与面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"creative-secondary","school_zh":"启思中学","school_en":"Creative Secondary School","grade":"s1","year":"unknown","year_label":"年份未注明","type":"mixed","title":"启思中学 · 年份未注明 · 中一 · 考试与面试","anonymous":true,"source_ids":["CSS-S1-ABILITY-REFERENCE","CSS-S1-JAN-INTERACTIVE","CSS-S1-JUNE-INTERACTIVE","CSS-S1-MAY-WAITING","CSS002"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/creative-secondary/s1/unknown-mixed.md","filePath":"reports/creative-secondary/s1/unknown-mixed.md"}'),s={name:"reports/creative-secondary/s1/unknown-mixed.md"};function i(l,e,p,h,d,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="启思中学-·-年份未注明-·-中一-·-考试与面试" tabindex="-1">启思中学 · 年份未注明 · 中一 · 考试与面试 <a class="header-anchor" href="#启思中学-·-年份未注明-·-中一-·-考试与面试" aria-label="Permalink to &quot;启思中学 · 年份未注明 · 中一 · 考试与面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/creative-secondary">← 返回启思中学资料库</a></p><blockquote><p>以下为匿名化、校对后的反馈摘录；部分内容保留原有表达。历史反馈仅供参考，具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-css-s1-ability-reference" tabindex="-1">资料来源：启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css-s1-ability-reference" aria-label="Permalink to &quot;资料来源：启思中学中一春季及秋季入学考经 .pdf {#record-css-s1-ability-reference}&quot;">​</a></h2><p><strong>资料类型：</strong> 入学能力要求与语言参考样文</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>适用范围：</strong></p><h3 id="能力要求与参考样文" tabindex="-1">能力要求与参考样文 <a class="header-anchor" href="#能力要求与参考样文" aria-label="Permalink to &quot;能力要求与参考样文&quot;">​</a></h3><p>以下为中一入学能力参考，语言分为 Language and Literature（语言与文学）及 Language Acquisition（语言习得）。参考样文用于了解能力层次，不代表每位考生都会遇到相同文章或题目。中文语言习得课程的适用资格须按学校及教育局要求确认。</p><h3 id="申请资格与课程背景" tabindex="-1">申请资格与课程背景 <a class="header-anchor" href="#申请资格与课程背景" aria-label="Permalink to &quot;申请资格与课程背景&quot;">​</a></h3><p>申請資格：完成本地小六教育、海外小學教育、IB PYP課程或同等小學課程。特殊情況（如學年中轉學）將按個別情況考慮，錄取不取決於年齡或就學年數。</p><p>學校為直資學校，採用香港初中課程及MYP框架。只有符合教育局定義的非華語學生才能修讀中文語言習得課程；教育局會審視學生的語言背景、家用語言及家庭背景等情況。</p><p><a href="/hk-exam-web/assets/exam-papers/css-s1-language-reference.pdf">查看语言能力参考全文及笔画示例（PDF）</a></p><p><a href="/hk-exam-web/reports/creative-secondary/s1/unknown-mixed#record-css002">查看11月考生反馈：三角形面积、体积、公因数公倍数及《悯农》问答</a></p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><h3 id="面试知识范围" tabindex="-1">面试知识范围 <a class="header-anchor" href="#面试知识范围" aria-label="Permalink to &quot;面试知识范围&quot;">​</a></h3><p>申請人需熟悉以下課題：</p><ul><li>數字混合運算</li><li>小數</li><li>分數</li><li>百分比</li><li>近似值</li><li>最大公因數與最小公倍數</li><li>簡易方程</li><li>簡單圖形面積與體積</li></ul></blockquote><blockquote><p><strong>中文：Language Acquisition：</strong> 普通话</p><h3 id="参考层次" tabindex="-1">参考层次 <a class="header-anchor" href="#参考层次" aria-label="Permalink to &quot;参考层次&quot;">​</a></h3><p>以下只是參考，會按學生能力與背景作出評估。教學語言為普通話。</p><h3 id="中文书写笔画" tabindex="-1">中文书写笔画 <a class="header-anchor" href="#中文书写笔画" aria-label="Permalink to &quot;中文书写笔画&quot;">​</a></h3><p>大致認識中文書寫筆劃，包括基本筆劃及複合筆劃。具体字形见下方示例页。</p><h3 id="常用中文字词" tabindex="-1">常用中文字词 <a class="header-anchor" href="#常用中文字词" aria-label="Permalink to &quot;常用中文字词&quot;">​</a></h3><p>大致認識以下中文字詞：</p><ul><li>一、二、三、四、五、六、七、八、九、十、百、千、萬、是、個</li><li>你、我、的、朋友、好</li><li>日、生日、月、星期、今天、昨天、明天</li><li>早上、晚上、上午、中午、下午</li></ul><h3 id="普通话拼音" tabindex="-1">普通话拼音 <a class="header-anchor" href="#普通话拼音" aria-label="Permalink to &quot;普通话拼音&quot;">​</a></h3><p>大致認識普通話拼音。</p><p>韻母：</p><ul><li>a o e i u ü er</li><li>ai ei ao ou</li><li>ia ie iao iou(iu)</li><li>ua uo uai uei(ui)</li><li>an en ang eng ong</li><li>ian in iang ing iong</li><li>uan uen(un) uang ueng</li><li>üe üan ün</li></ul><p>聲母：</p><ul><li>b p m f d t n l</li><li>g k h j q x</li><li>zh ch sh r</li><li>z c s</li></ul><p>另包括聲調辨認。筆劃及聲調示例：</p><p><img src="'+n+'" alt="中文语言习得：笔画、字词与拼音示例"></p><h3 id="简单中文对答" tabindex="-1">简单中文对答 <a class="header-anchor" href="#简单中文对答" aria-label="Permalink to &quot;简单中文对答&quot;">​</a></h3><p>大致能作簡單中文對答：</p><ol><li>今天幾號？——九月二號。</li><li>昨天星期幾？——星期三。</li><li>明天幾號？——明天三號。</li><li>你的生日是幾月幾號？——十月二十號。</li><li>現在幾點？——現在差五分六點。</li></ol></blockquote><blockquote><p><strong>中文：Language and Literature：</strong> 普通话</p><h3 id="白话文阅读" tabindex="-1">白话文阅读 <a class="header-anchor" href="#白话文阅读" aria-label="Permalink to &quot;白话文阅读&quot;">​</a></h3><p>能理解小六程度的白話文。以下保留完整参考篇章：</p><p>①對很多人來說，寵物既是可愛的朋友，也是可親的家人。而對我來說呢？寵物卻是可敬的老師，讓我上了寶貴的一課。</p><p>②那年是鼠年，為了迎合潮流，我懇求媽媽送我一隻初生的小倉鼠。小倉鼠常常「吱吱」地叫，所以我給牠取名芝芝。芝芝全身長有棕色的毛，只有肚子是白色的軟毛，好像披上了一件棕色的外套。牠身形只有一個網球的大小，捧在手上，令人愛不釋手。</p><p>③農曆新年假期過後，是學校的期中試。每天上學、做功課、補習、參加課外活動，使我忙得不可開交，我又如何好好照顧芝芝呢？當時，我給自己一個冠冕堂皇的藉口─忙。最初幾天，經媽媽勸導，我勉強地擠出一點時間照顧牠；當考試逼近，我便把承諾拋諸腦後。「少照顧一次兩次有甚麼大礙？牠不是好好的嗎？」那時，媽媽還提醒我照顧芝芝，但我一直沒有留意。</p><p>④期中試結束，我赫然發現芝芝沒有了往日東奔西跑的活力，取而代之是發呆、打嗝。最初我不以為然，突然有一天，牠腹瀉不止，我送牠到寵物診所時，一心以為只是小毛病。不料醫生說芝芝的病情很嚴重，死亡率高達八成以上，需要立即做手術。我聽到這個消息，簡直是晴天霹靂，都怪我終日冷待牠，又不定時餵食和清理，以致牠患病。想到這裏，我既擔心又慚愧。幸好，芝芝在醫生努力搶救下，保住了性命。</p><p>⑤芝芝，謝謝你活下來，謝謝你給我上了寶貴的一課，讓我明白飼養寵物是終生的承諾，而非一時的興致。一時的粗心和疏懶差點兒害了一條生命。學習和成長的道路不也相似嗎？只有認真和盡責，才能結出美好的果子。謝謝你，親愛的芝芝。</p><h3 id="文言作品阅读" tabindex="-1">文言作品阅读 <a class="header-anchor" href="#文言作品阅读" aria-label="Permalink to &quot;文言作品阅读&quot;">​</a></h3><p>能理解小六程度的文言作品。</p><p>《九月九日憶山東兄弟》——唐・王維</p><p>獨在異鄉為異客，</p><p>每逢佳節倍思親。</p><p>遙知兄弟登高處，</p><p>遍插茱萸少一人。</p><p>教學語言為普通話。</p></blockquote><blockquote><p><strong>英语：Language Acquisition：</strong> 英语</p><h3 id="the-enchanted-garden" tabindex="-1">The Enchanted Garden <a class="header-anchor" href="#the-enchanted-garden" aria-label="Permalink to &quot;The Enchanted Garden&quot;">​</a></h3><p>In a beautiful village settled between rolling hills, there was a secret garden known only to a few. The garden, hidden behind an old, vine-covered wall, was said to have a touch of magic. It was a place where flowers bloomed year-round, even when snow covered the rest of the village.</p><p>The groundskeeper was a kind woman named Eliza, who had cared for it for decades. Each morning, as the sun cast its first rays, she would lovingly water the flowers. The flowers would sway and bloom as if they were dancing in response to her care. Their sweet smells would fill the air, bringing joy to all who caught a whiff.</p><p>Children, in particular, were drawn to the garden. They believed that making a wish in the garden would make it come true. They would tiptoe through the garden, whispering their secrets to the colorful blossoms. It was a place of dreams, where the impossible felt possible.</p><p>Eliza, with her wrinkled hands and warm smile, would often sit on an old bench in the garden, telling the children stories of its magical history. She would recount tales of fairies who visited in the moonlight and the mischievous gnomes who played among the petals.</p><p>One day, a curious girl named Sarah made her way to the garden - in her hand, a secret wish she was too afraid to share with anyone. With shaking fingers, she whispered to the flowers. Little did she know, the garden was listening, ready to make her dreams come true.</p></blockquote><blockquote><p><strong>英语：Language and Literature：</strong> 英语</p><h3 id="the-forgotten-library" tabindex="-1">The Forgotten Library <a class="header-anchor" href="#the-forgotten-library" aria-label="Permalink to &quot;The Forgotten Library&quot;">​</a></h3><p>Nestled in a serene corner of the city lay a hidden gem known as &quot;The Forgotten Library.&quot; For centuries, this noble institution had stood as a guardian of knowledge, its halls housing a boundless treasure trove of wisdom.</p><p>Stepping through the library&#39;s grand doors was like entering a realm of enchantment. Countless ancient leather-bound books adorned the shelves, their pages holding the wisdom of countless years. In the quiet corners, dusty books recounted the heroic sagas of forgotten champions and revealed tales of uncharted adventures.</p><p>Yet, what set this library apart was its extraordinary spiral staircase, a seemingly boundless ascent that led to the highest shelves, where the most mysterious and elusive texts were safeguarded. Eager visitors would embark on the climb, driven by a thirst for hidden truths and a desire to discover the secrets concealed within those up-so-high volumes.</p><p>People, hailing from distant lands, made journeys to &quot;The Forgotten Library.&quot; Scholars came to seek rare manuscripts, while dreamers found comfort and inspiration within its pages. It was a realm where the time seemed to stop, and stories whispered from every corner, patiently waiting to be unearthed by those who dared to explore.</p><p>&quot;The Forgotten Library&quot; was not merely a place; it was a sanctuary of knowledge and imagination, where the past blended with the present, and the mysteries of the world lay within reach of those who sought to uncover them.</p></blockquote><h2 id="record-css-s1-jan-interactive" tabindex="-1">资料来源：启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css-s1-jan-interactive" aria-label="Permalink to &quot;资料来源：启思中学中一春季及秋季入学考经 .pdf {#record-css-s1-jan-interactive}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 1月</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>个人及阅读问答</strong></p><p>个人问答、白话文阅读理解与古诗分析。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读与个人问题</strong></p><p>朗读文章后回答问题；个人问题围绕家庭与生活城市，也会追问“你数学好，是因为天赋还是其他原因？”家长认为问题因人而异，难度不高。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>平板答题</strong></p><p>使用iPad答题；该考生反馈用时10分钟完成。</p></blockquote><h2 id="record-css-s1-june-interactive" tabindex="-1">资料来源：启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css-s1-june-interactive" aria-label="Permalink to &quot;资料来源：启思中学中一春季及秋季入学考经 .pdf {#record-css-s1-june-interactive}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 6月</p><h3 id="轮次未注明-·-请以当次考试通知为准-2" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-2" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>申请与评估</strong></p><p>网上申请时提交学生自我介绍视频；获邀后参加中文、英文与数学评估。该场以计算机答题和师生问答进行，没有另设集中纸笔考试。</p></blockquote><blockquote><p><strong>数学：</strong> 英语，附中文标注</p><p><strong>计算机答题</strong></p><p>以计算机完成英文数学题，题目附中文标注。考生认为内容较简单。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，繁体字</p><p><strong>阅读与文言理解</strong></p><p>阅读繁体中文文章；文言文部分需解释文意。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>口语交流</strong></p><p>包含口语提问、对话与追问。家长认为交流内容有一定深度。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>教育理念</strong></p><p>老师与家长交流学校教育理念、毕业生发展，以及如何让学生从生活与学习中建立联系、培养独立思考和解决问题的能力。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>学校印象</strong></p><p>学生对教学资源和科技体验印象较好，特别提到食品科学；家长认为交流体验愉快。</p></blockquote><h2 id="record-css-s1-may-waiting" tabindex="-1">资料来源：启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css-s1-may-waiting" aria-label="Permalink to &quot;资料来源：启思中学中一春季及秋季入学考经 .pdf {#record-css-s1-may-waiting}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 5月</p><h3 id="轮次未注明-·-请以当次考试通知为准-3" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-3" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>评估形式</strong></p><p>以平板答题配合老师问答进行。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读问答</strong></p><p>阅读一篇文章后，回答老师提出的问题。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>学科难度</strong></p><p>考生认为数学与语文较简单。</p><p><strong>考前准备</strong></p><p>这是该考生当时参加的第一场考试。家长安排过一次辅导课，预先准备可能被问到的问题。</p><p><strong>候补结果</strong></p><p>考后获得候补资格。家长向学校查询时获告知处于候补名单中段，老师表示按往年经验，仍很有机会等到录取。其后于7月16日收到正式录取通知，家长认为收到通知的时间较晚。</p></blockquote><h2 id="record-css002" tabindex="-1">资料来源：启思中学七年级插班.png；启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css002" aria-label="Permalink to &quot;资料来源：启思中学七年级插班.png；启思中学中一春季及秋季入学考经 .pdf {#record-css002}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生反馈</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 11月</p><h3 id="轮次未注明-·-请以当次考试通知为准-4" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-4" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>考点范围</strong></p><p>题目涉及三角形面积、体积、最小公倍数及最大公因数。</p></blockquote><blockquote><p><strong>中文：</strong> 中文（口语语种未注明）</p><p><strong>文章阅读</strong></p><p>先阅读较长的文章，再回答教师提出的几个问题。</p><p><strong>古诗理解与应用</strong></p><p>随后阅读《悯农》，说明诗中表达的思想感情，并回答若将诗张贴在学校，应选择哪个位置。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>自我介绍与阅读</strong></p><p>先作自我介绍，再阅读一篇关于水的文章，回答教师的问题。</p><p><strong>向教师提问</strong></p><p>最后由考生向教师提出与学校有关的问题。</p></blockquote>',53)])])}const b=o(s,[["render",i]]);export{u as __pageData,b as default};
